pub fn unit_sync(items: &[Spanned<Item>], names: &winnow_grammar::InternerContext, unaliased: &mut impl FnMut(&str) -> String, holes_of: &mut impl FnMut(&Expr) -> Vec<Expr>, own: &Ledger, library: &Ledger, graph: &mut SyncGraph) {
    for item in items.iter() {
        match &item.node {
            Item::Fn { name, args, body, is_sync, sync_by, .. } => {
                let is_sync = *is_sync; let name = *name;
                let key = key_of_function((name).as_ref(), "", names);
                let mut node = sync_node(&seen_in(body, names, &mut *unaliased, &mut *holes_of, &mut no_root, false), items, &code_of(args, body, names), names, own, library, graph.unit);
                sync_methods(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut node);
                declared_sync(is_sync, sync_by, &mut node);
                graph.nodes.insert(key, node);
            },
            Item::Impl { trait_name, target, methods, .. } => {
                let trait_name = *trait_name;
                let owner = nikaia_std::block::Text::from(names.resolve(target.name).to_string());
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, args, body, is_sync, sync_by, .. } => {
                            let is_sync = *is_sync; let name = *name;
                            let key = key_of_function((name).as_ref(), &owner, names);
                            let mut node = sync_node(&seen_in(body, names, &mut *unaliased, &mut *holes_of, &mut no_root, false), items, &code_of(args, body, names), names, own, library, graph.unit);
                            sync_methods(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut node);
                            declared_sync(is_sync, sync_by, &mut node);
                            declared_by((trait_name).as_ref(), &key_of_function((name).as_ref(), "", names), names, own, library, &mut node);
                            graph.nodes.insert(key, node);
                        },
                        _ => { },
                    }
                }
            },
            Item::Trait { name, methods, .. } => {
                let name = *name;
                let declaring = nikaia_std::block::Text::from(names.resolve(name).to_string());
                for method in methods.iter() {
                    let key = format!("{}::{}", declaring, names.resolve(method.node.name));
                    graph.nodes.insert(key, leaf(!method.node.is_sync));
                }
            },
            Item::Grammar(def) => {
                let named = nikaia_std::block::Text::from(names.resolve(def.name).to_string());
                for rule in def.rules.iter() { if rule.is_entry { graph.nodes.insert(format!("{}::{}", named, names.resolve(rule.name)), leaf(false)); } }
            },
            _ => { },
        }
    }
}

pub(crate) fn declared_sync(is_sync: bool, sync_by: &[winnow_grammar::Symbol], node: &mut SyncNode) {
    if !is_sync || !sync_by.is_empty() { return; }
    node.reach.blocked = false;
    node.reach.calls.clear();
    node.reach.through_code.clear();
}

pub(crate) fn leaf(blocked: bool) -> SyncNode { SyncNode { reach: SyncReach { blocked, calls: collections::BTreeSet::new(), through_code: collections::BTreeSet::new(), pauses_here: false }, site: None, unit: 0 } }

pub(crate) fn declared_by(trait_name: Option<&winnow_grammar::Symbol>, method: &str, names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, node: &mut SyncNode) {
    let named = match trait_name { Some(__nikaia_value) => __nikaia_value, None => return };
    let declared = format!("{}::{}", names.resolve(*named), method);
    if own.functions.contains_key(&declared) { node.reach.calls.insert(declared); } else if library.functions.contains_key(&declared) {
        let entry = nikaia_std::index::or(match *nikaia_std::index::get(&library.functions, &declared) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || FnContract::empty());
        if !entry.sync_claim.is_sync() { node.reach.calls.insert(declared); }
    }
}

pub(crate) fn code_of(args: &[FnArg], body: &Block, names: &winnow_grammar::InternerContext) -> collections::BTreeMap<String, bool> {
    let mut code: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    for arg in args.iter() {
        let declared = match (*arg.ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
        code.insert(nikaia_std::block::Text::from(names.resolve(arg.name).to_string()), !declared.is_sync);
    }
    code_bound_in(body, names, &mut code);
    code
}

pub(crate) fn code_bound_in(block: &Block, names: &winnow_grammar::InternerContext, code: &mut collections::BTreeMap<String, bool>) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { names: bound, ty, value, .. } => {
                if bound.len() == 1 {
                    let name = nikaia_std::block::Text::from(names.resolve(*unsafe { nikaia_std::proven::read(&bound, (0) as usize) }).to_string());
                    let written = code_written((ty).as_ref());
                    if written.is_some() { code.insert(name, nikaia_std::index::or(written, || false)); } else {
                        let from = code_source(value, names, &code);
                        if from.is_some() { code.insert(name, nikaia_std::index::or(from, || false)); }
                    }
                }
            },
            _ => { },
        }
        for expr in check_visit_stmt(&stmt.node) {
            match expr {
                Expr::Match { value, arms, .. } => {
                    let value = nikaia_std::boxed::open(value);
                    let from = match code_source(value, names, &code) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    for arm in arms.iter() {
                        match &arm.pattern {
                            MatchPattern::Path(segments) => { if segments.len() == 1 { code.insert(nikaia_std::block::Text::from(names.resolve(*unsafe { nikaia_std::proven::read(&segments, (0) as usize) }).to_string()), from); } },
                            _ => { },
                        }
                    }
                },
                _ => { },
            }
        }
        for inner in check_visit_stmt_blocks(&stmt.node) { code_bound_in(inner, names, code); }
    }
}

pub(crate) fn code_written(ty: Option<&Type>) -> Option<bool> {
    let written = match ty { Some(__nikaia_value) => __nikaia_value, None => return None };
    let declared = match (*written.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(!declared.is_sync)
}

pub(crate) fn code_source(value: &Expr, names: &winnow_grammar::InternerContext, code: &collections::BTreeMap<String, bool>) -> Option<bool> {
    match value {
        Expr::Variable(name, _) => { let name = *name; code.get(names.resolve(name)).copied() },
        Expr::Coalesce { value: held, .. } => { let held = nikaia_std::boxed::open(held); code_source(held, names, code) },
        _ => None,
    }
}

pub(crate) fn sync_node(seen: &[Seen], items: &[Spanned<Item>], code: &collections::BTreeMap<String, bool>, names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, unit: i64) -> SyncNode {
    let mut node = SyncNode { reach: SyncReach { blocked: false, calls: collections::BTreeSet::new(), through_code: collections::BTreeSet::new(), pauses_here: false }, site: None, unit };
    for one in seen.iter() {
        match one {
            Seen::Joins { construct, span } => {
                node.reach.blocked = true;
                first_site(span, &format!("an `{}` block", construct), &mut node);
            },
            Seen::Call { name, span, .. } => { sync_call((callee_named(names, nikaia_std::block::Text::from(name.to_string()), own, library, items)).as_ref(), span, code, &mut node); },
            Seen::Spawn { span } => { sync_call(Some(&Callee::Opaque(None)), span, code, &mut node); },
            Seen::Opaque { span } => { sync_call(Some(&Callee::Opaque(None)), span, code, &mut node); },
            _ => { },
        }
    }
    node.reach.pauses_here = node.site.is_some();
    node
}

pub(crate) fn sync_call(callee: Option<&Callee>, span: &Span, code: &collections::BTreeMap<String, bool>, node: &mut SyncNode) {
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    match known {
        Callee::Own(name) => { node.reach.calls.insert(nikaia_std::block::Text::from(name.to_string())); },
        Callee::Library { key, never_pauses } => {
            let never_pauses = *never_pauses;
            if !never_pauses {
                node.reach.blocked = true;
                first_site(span, &format!("`{}`", key), node);
            }
        },
        Callee::Opaque(name) => { opaque_call((name).as_deref(), span, code, node); },
        _ => { },
    }
}

pub(crate) fn opaque_call(name: Option<&str>, span: &Span, code: &collections::BTreeMap<String, bool>, node: &mut SyncNode) {
    if a_stop(name) { return; }
    if name.is_none() {
        node.reach.blocked = true;
        first_site(span, "something this compiler cannot see the end of", node);
        return;
    }
    let called = match name { Some(__nikaia_value) => __nikaia_value, None => return };
    if code.contains_key(called) {
        if nikaia_std::index::or(*nikaia_std::index::get(&code, called), || false) {
            first_site(span, &format!("`{}`", called), node);
            node.reach.through_code.insert(nikaia_std::block::Text::from(called.to_string()));
        }
        return;
    }
    node.reach.blocked = true;
    first_site(span, &format!("`{}`", called), node);
}

pub(crate) fn first_site(span: &Span, what: &str, node: &mut SyncNode) { if node.site.is_none() { node.site = Some(Site { span: span.clone(), what: nikaia_std::block::Text::from(what.to_string()) }); } }

pub(crate) fn sync_methods(resolved: Option<&MethodsCalled>, own: &Ledger, library: &Ledger, node: &mut SyncNode) {
    let known = match resolved { Some(__nikaia_value) => __nikaia_value, None => return };
    if known.unseen { node.reach.blocked = true; }
    for callee in known.resolved.iter() { if own.functions.contains_key(callee) { node.reach.calls.insert(nikaia_std::block::Text::from(callee.to_string())); } else if !never_pauses_in(library, callee) { node.reach.blocked = true; } }
}

pub(crate) fn never_pauses_in(library: &Ledger, callee: &str) -> bool {
    let contract = match *nikaia_std::index::get(&library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return false };
    contract.sync_claim.is_sync()
}

