pub fn sync_violations(view: &ParsedView<'_, '_, '_, '_, '_, '_, '_>, own: &Ledger, library: &Ledger, holes_of: &mut impl FnMut(&Expr) -> Vec<Expr>) -> Vec<Violation> {
    let mut found = unit_violations(view.items, view.words, &mut |name| { view.unaliased(name) }, &mut *holes_of, own, library);
    found.sort_by_key(|v| { v.span.start });
    found
}

pub(crate) fn unit_violations(items: &[Spanned<Item>], names: &winnow_grammar::InternerContext, unaliased: &mut impl FnMut(&str) -> String, holes_of: &mut impl FnMut(&Expr) -> Vec<Expr>, own: &Ledger, library: &Ledger) -> Vec<Violation> {
    let mut found: Vec<Violation> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Fn { name, args, body, is_sync, sync_by, .. } => {
                let is_sync = *is_sync; let name = *name;
                let promise = match promise_of(&key_of_function((name).as_ref(), "", names), args, body, is_sync, sync_by, names) { Some(__nikaia_value) => __nikaia_value, None => continue };
                violations_in(&seen_in(body, names, &mut *unaliased, &mut *holes_of, &mut no_root, false), &promise, items, names, own, library, &mut found);
            },
            Item::Impl { target, methods, .. } => {
                let owner = nikaia_std::block::Text::from(names.resolve(target.name).to_string());
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, args, body, is_sync, sync_by, .. } => {
                            let is_sync = *is_sync; let name = *name;
                            let promise = match promise_of(&key_of_function((name).as_ref(), &owner, names), args, body, is_sync, sync_by, names) { Some(__nikaia_value) => __nikaia_value, None => continue };
                            violations_in(&seen_in(body, names, &mut *unaliased, &mut *holes_of, &mut no_root, false), &promise, items, names, own, library, &mut found);
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    once_per_site(&found)
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub(crate) fn once_per_site(found: &[Violation]) -> Vec<Violation> {
    let mut said: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut kept: Vec<Violation> = vec![];
    kept.reserve(found.iter().size_hint().0); for v in found.iter() {
        let key = format!("{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}", v.span.start, v.span.end, v.caller, v.promise, v.callee, v.from_library, v.unpromised, v.construct);
        if said.contains(&key) { continue; }
        said.insert(key);
        kept.push(v.clone());
    }
    kept
}

pub fn unit_pausing(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &mut impl FnMut(&str) -> String, holes_of: &mut impl FnMut(&Expr) -> Vec<Expr>, own: &Ledger, library: &Ledger, wanted: &[String]) -> Vec<bool> {
    let mut answers: Vec<bool> = vec![];
    answers.reserve(wanted.iter().size_hint().0); for one in wanted.iter() {
        let mut pauses = false;
        for item in program.items.iter() {
            match &item.node {
                Item::Fn { name, args, body, .. } => {
                    let name = *name;
                    let key = key_of_function((name).as_ref(), "", names);
                    if key == *one {
                        let promise = match promise_of(&key, args, body, true, &vec![], names) { Some(__nikaia_value) => __nikaia_value, None => continue };
                        let mut found: Vec<Violation> = vec![];
                        violations_in(&seen_in(body, names, &mut *unaliased, &mut *holes_of, &mut no_root, false), &promise, &program.items, names, own, library, &mut found);
                        pauses = !found.is_empty();
                    }
                },
                _ => { },
            }
        }
        answers.push(pauses);
    }
    answers
}

pub(crate) fn promise_of(caller: &str, args: &[FnArg], body: &Block, is_sync: bool, sync_by: &[winnow_grammar::Symbol], names: &winnow_grammar::InternerContext) -> Option<Promise> {
    if !is_sync && sync_by.is_empty() { return None; }
    let mut allowed: collections::BTreeSet<String> = collections::BTreeSet::new();
    for arg in args.iter() {
        let declared = match (*arg.ty.code).as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
        if declared.is_sync { allowed.insert(nikaia_std::block::Text::from(names.resolve(arg.name).to_string())); }
    }
    #[allow(unused_mut)] let mut named: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    named.reserve(sync_by.iter().size_hint().0); for one in sync_by.iter() {
        let one = *one;
        let parameter = nikaia_std::block::Text::from(names.resolve(one).to_string());
        allowed.insert(nikaia_std::block::Text::from(parameter.to_string()));
        named.push(parameter);
    }
    let mut kept: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    for parameter in allowed.iter() { kept.insert(nikaia_std::block::Text::from(parameter.to_string()), false); }
    code_bound_in(body, names, &mut kept);
    for (local, pauses) in kept.iter() {
        let pauses = nikaia_std::num::value(pauses);
        if !pauses { allowed.insert(nikaia_std::block::Text::from(local.to_string())); }
    }
    let mut promise: String = String::from("sync"); #[allow(unused_mut, clippy::redundant_locals)] let mut named = named;
    if !named.is_empty() {
        let joined = nikaia_std::block::Text::from(named.join(", "));
        promise = format!("sync({})", joined);
    }
    Some(Promise { caller: nikaia_std::block::Text::from(caller.to_string()), promise, allowed })
}

pub(crate) fn violations_in(seen: &[Seen], promise: &Promise, items: &[Spanned<Item>], names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, found: &mut Vec<Violation>) {
    for one in seen.iter() {
        match one {
            Seen::Joins { construct, span } => { found.push(violation(promise, span, construct, false, false, true)); },
            Seen::Call { name, span, .. } => {
                if !name.contains("::") && promise.allowed.contains(name) { continue; }
                pausing_call((callee_named(names, nikaia_std::block::Text::from(name.to_string()), own, library, items)).as_ref(), span, promise, own, found);
            },
            Seen::Spawn { span } => { pausing_call(Some(&Callee::Opaque(None)), span, promise, own, found); },
            Seen::Opaque { span } => { pausing_call(Some(&Callee::Opaque(None)), span, promise, own, found); },
            _ => { },
        }
    }
}

pub(crate) fn pausing_call(callee: Option<&Callee>, span: &Span, promise: &Promise, own: &Ledger, found: &mut Vec<Violation>) {
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    match known {
        Callee::Own(name) => {
            let contract = match *nikaia_std::index::get(&own.functions, name) { Some(__nikaia_value) => __nikaia_value, None => return };
            if !contract.sync_claim.is_sync() { found.push(violation(promise, span, name, false, unpromised(&contract.sync_claim), false)); }
        },
        Callee::Library { key, never_pauses } => {
            let never_pauses = *never_pauses;
            if !never_pauses { found.push(violation(promise, span, key, true, false, false)); }
        },
        Callee::Opaque(name) => {
            if a_stop((name).as_deref()) { return; }
            let called = nikaia_std::index::or(match name {
                Some(__nikaia_it) => Some(nikaia_std::block::Text::from(__nikaia_it.to_string())),
                None => None,
            }, || "something this compiler cannot resolve".into());
            found.push(violation(promise, span, &called, false, false, false));
        },
        _ => { },
    }
}

pub(crate) fn a_stop(name: Option<&str>) -> bool {
    let called = match name { Some(__nikaia_value) => __nikaia_value, None => return false };
    called == "panic"
}

pub(crate) fn unpromised(claim: &Sync) -> bool { claim.is_unpromised() }

pub(crate) fn violation(promise: &Promise, span: &Span, callee: &str, from_library: bool, unpromised: bool, construct: bool) -> Violation { Violation { span: span.clone(), caller: nikaia_std::block::Text::from(promise.caller.to_string()), promise: nikaia_std::block::Text::from(promise.promise.to_string()), callee: nikaia_std::block::Text::from(callee.to_string()), from_library, unpromised, construct } }

pub(crate) fn sync_test_node(graph: &mut collections::BTreeMap<String, SyncReach>, name: String, blocked: bool, calls: &[&'static str]) {
    let mut reach = SyncReach { blocked, calls: collections::BTreeSet::new(), through_code: collections::BTreeSet::new(), pauses_here: blocked };
    for callee in calls.iter() {
        let callee = *callee;
        reach.calls.insert(nikaia_std::block::Text::from(callee.to_string()));
    }
    graph.insert(name, reach);
}

